#!/usr/bin/env bash
set -euo pipefail
BACKUP="/srv/ai-data/hermes/global-resource-queue-backup-v1";HERMES_HOME="/srv/ai-data/hermes";HERMES_SOURCE="${HERMES_HOME}/hermes-agent";HERMES_TURN="${HERMES_SOURCE}/agent/turn_api_request.py";GATEWAY_HOME="/opt/ai-gateway";GATEWAY_PY="${GATEWAY_HOME}/.venv/bin/python";GATEWAY_SRC="${GATEWAY_HOME}/src/ai_bridge";LIBEXEC="/usr/local/libexec/ai-server"
[[ -d "$BACKUP" ]] || { echo "FAIL: backup missing: $BACKUP";exit 1; }
restore_optional(){ local dst="$1" name="$2";if [[ -e "$BACKUP/$name.absent" ]];then sudo rm -f "$dst";elif [[ -e "$BACKUP/$name" ]];then sudo cp -a "$BACKUP/$name" "$dst";else echo "FAIL: backup entry missing: $name";exit 1;fi; }
echo "===== ROLLBACK GLOBAL RESOURCE QUEUE =====";restore_optional "$GATEWAY_SRC/gateway/scheduler.py" gateway-scheduler.py;restore_optional "$GATEWAY_SRC/gateway/resource_leases.py" gateway-resource_leases.py;restore_optional "$GATEWAY_SRC/gateway/app.py" gateway-app.py;restore_optional "$GATEWAY_SRC/settings.py" gateway-settings.py;sudo -u harrypotter "$GATEWAY_PY" -m pip install --disable-pip-version-check "$GATEWAY_HOME" >/dev/null;sudo systemctl restart ai-gateway.service
restore_optional "$HERMES_TURN" hermes-turn_api_request.py;restore_optional /usr/local/bin/hermes-foto-dispatch hermes-foto-dispatch;restore_optional "$LIBEXEC/hermes_foto_dispatch_base.py" hermes_foto_dispatch_base.py;restore_optional "$LIBEXEC/hermes_resource_queue.py" hermes_resource_queue.py;restore_optional "$LIBEXEC/hermes_video_dispatch.py" hermes_video_dispatch.py;restore_optional "$LIBEXEC/hermes_video_dispatch_stage30.py" hermes_video_dispatch_stage30.py;systemctl --user restart hermes-gateway.service;sleep 1
[[ "$(systemctl is-active ai-gateway.service 2>/dev/null || true)" == active ]] || { echo "FAIL: ai-gateway inactive";exit 1; };[[ "$(systemctl --user is-active hermes-gateway.service 2>/dev/null || true)" == active ]] || { echo "FAIL: Hermes inactive";exit 1; };echo "PASS: global resource queue rolled back to the pre-install state"
